80}, \"suggestions\": [], \"distortionRisk\": \"None\", \"missingKeywords\": []}','2026-11-03 08:38:29'),(4,3,3,NULL,'ats',85,'{\"score\": 85, \"checks\": {\"language\": true, \"dateFormat\": true, \"phoneFormat\": true}, \"rating\": \"Good\", \"summary\": \"This resume effectively highlights the candidate\'s experience as a Full Stack Developer with relevant skills and accomplishments. However, some keywords could be better utilized to enhance ATS compatibility.\", \"sections\": {\"skills\": 80, \"summary\": 90, \"keywords\": 75, \"education\": 90, \"experience\": 85, \"formatting\": 90, \"actionVerbs\": 85, \"contactInfo\": 100, \"readability\": 90, \"achievements\": 80}, \"suggestions\": [{\"fix\": \"Incorporate keywords like \'JavaScript\', \'Agile\', \'UI/UX\', \'API\', \'Collaboration\', \'Testing\', and \'Debugging\' in the skills section.\", \"issue\": \"Missing relevant keywords for ATS\", \"section\": \"skills\"}, {\"fix\": \"Refine the summary to include specific keywords from the job description such as \'API development\', \'collaboration with design teams\', and emphasize \'Agile methodology\'.\", \"issue\": \"Could be more concise and keyword rich\", \"section\": \"summary\"}, {\"fix\": \"Include more quantifiable metrics to highlight the impact of achievements, such as the number of users served or performance improvements.\", \"issue\": \"Limited use of quantifiable achievements\", \"section\": \"achievements\"}], \"distortionRisk\": \"Low\", \"missingKeywords\": [\"JavaScript\", \"Agile\", \"UI/UX\", \"API\", \"Collaboration\", \"Testing\", \"Debugging\"]}','2026-11-03 08:38:30');
