  `strengths` json DEFAULT NULL,
  `summary` text,
  `recommendation` varchar(20) DEFAULT NULL,
  `status` varchar(20) DEFAULT 'Review',
  `resume_text` mediumtext,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `user_id` int DEFAULT NULL,
  `resume_hash` varchar(64) DEFAULT NULL,
  `parsed` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `job_id` (`job_id`),
  CONSTRAINT `candidates_ibfk_1` FOREIGN KEY (`job_id`) REFERENCES `jobs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
